export interface ContactMatch { orgName: string; department: string; phone: string; address?: string; duty: string; }

export function matchContact(intent: IntentKey, region: string): ContactMatch {
  const info = INTENTS.find((item) => item.key === intent);
  if (!info) return { orgName: "농지은행", department: "상담 담당", phone: HUMAN_SUPPORT_PHONE, duty: "농지은행 상담" };
  if (info.org === "farmland_bank") {
    // 임실군의 임대수탁 업무는 전주완주임실지사가 아닌 임실지부가 담당한다.
    if (
      region === "임실군" &&
      (intent === "farmland_lease_trust_out" || intent === "farmland_lease_trust_in")
    ) {
      return {
        orgName: "한국농어촌공사 전주완주임실지사 임실지부 (농지은행)",
        department: info.label,
        phone: "063-270-0587",
        duty: info.meaning,
      };
    }
    const branchKey = REGION_TO_FB_BRANCH[region];
    const directPhone = branchKey ? info.contacts?.[branchKey] : undefined;
    const branchName = branchKey ? FARMLAND_BRANCH_LABELS[branchKey] : "대표";
    return {
      orgName: branchKey ? `한국농어촌공사 ${branchName}지사 (농지은행)` : "농지은행",
      department: info.label,
      phone: directPhone ?? HUMAN_SUPPORT_PHONE,
      duty: info.meaning,
    };
  }
  if (info.org === "municipal") {
    const office = MUNICIPAL_OFFICES.find((item) => item.region === region) ?? MUNICIPAL_FALLBACK;
    return { orgName: office.name, department: "농지이용실태조사 담당 (농업정책과)", phone: office.phone, duty: info.business };
  }
  if (info.org === "extension") {
    const office = EXTENSION_OFFICES.find((item) => item.region === region) ?? EXTENSION_OFFICES[0];
    if (!office) return { orgName: "전북특별자치도농업기술원", department: "영농기술·교육 담당", phone: "063-290-6000", duty: info.business };
    return { orgName: office.name, department: "영농기술·교육 담당", phone: office.phone, duty: office.duty };
  }
  const office = NAQS_OFFICES.find((item) => item.region.includes(region.replace(/[시군]$/, ""))) ?? NAQS_OFFICES.find((item) => item.region.includes(region)) ?? NAQS_OFFICES[0];
  if (!office) return { orgName: "국립농산물품질관리원 전북지원", department: "농업경영체·인증 담당", phone: "063-214-2160", duty: info.business };
  return { orgName: `국립농산물품질관리원 ${office.name}`, department: "농업경영체·인증 담당", phone: office.phone, duty: office.duty };
}

